function staffHTML(){return `<section data-testid="screen-staff">${u.user?`<p>ผู้ใช้จำลอง <strong>${esc(u.user.username)}</strong> · ${esc(u.user.role)}</p>${staffNav()}${u.page==='kitchen'&&can('kitchen')?kitchenHTML():u.page==='front'&&can('front')?frontHTML():''}`:'<p class="muted">กรุณาเข้าสู่ระบบจำลองเพื่อเปิดคิวครัวหรือหน้าร้าน</p>'}</section>`;}
function kitchenHTML(){const i=s.ingredients.find(i=>i.id===u.ingredient);const queue=[...s.orders].sort((a,b)=>a.received_at.localeCompare(b.received_at)||a.id-b.id);return `<div class="grid"><section class="panel"><h2>คิวครัว</h2><p class="muted">เรียงเวลาจำลองระดับวินาที แล้วเลขออเดอร์ • กดหนึ่งครั้งเลื่อนหนึ่งขั้น</p><div data-testid="kitchen-queue">${queue.map(o=>`<article class="ticket" data-testid="kitchen-order" data-order-id="${o.id}" data-received-at="${o.received_at}"><div class="split"><h3>#${o.id} · ${o.channel==='takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class="status">${statuses[o.status]}</span></div><time>${o.received_at}</time>${o.channel==='takeaway'?`<p>รับ ${esc(o.pickup_date)} ${esc(o.pickup_slot)}</p>`:''}${itemsHTML(o,'kitchen')}${button('btn-status-next',o.status<2?'เปลี่ยนเป็น '+statuses[o.status+1]:'เสร็จแล้ว','next-status',`data-id="${o.id}" ${o.status===2?'disabled':''}`)}</article>`).join('')||'<p class="empty">ยังไม่มีออเดอร์ในคิว</p>'}</div></section><section class="panel"><h2>ความพร้อมวัตถุดิบ</h2><label>วัตถุดิบ<select data-testid="ingredient-select">${choices(s.ingredients,u.ingredient)}</select></label><p data-testid="ingredient-status">${esc(i?.name)} · ${i?.available?'มี':'หมด'}</p><div class="row">${button('btn-out-of-stock','วัตถุดิบหมด','stock','data-available="false" class="danger"')}${button('btn-restock','กลับมามี','stock','data-available="true"')}</div><p class="muted">ผลจำลองตามแมป whole / option • เปิดคืนเมื่อไม่มีวัตถุดิบอื่นหมดค้าง และผู้จัดการไม่ได้ปิดขาย</p><p class="notice">DI-04/A-03 ยังไม่ยืนยันการเชื่อม US-20 กับ US-12/US-13</p></section></div>`;}
function frontHTML(){return `<section class="panel"><h2>หน้าร้าน • ออเดอร์และการรับเงิน</h2><p>เก็บยอด snapshot ขณะส่งแยกจากยอดหลังปรับจำลอง • สลิปและการรับเงิน <span class="tag">จำลอง</span></p><div data-testid="front-orders">${s.orders.map(o=>{const p=payment(o),old=o.session_id&&s.sessions.find(x=>x.id===o.session_id)?.state==='closed';return `<article data-testid="front-order" data-order-id="${o.id}" data-table-id="${esc(o.table_id)}" class="ticket"><div class="split"><h3>#${o.id} · ${o.channel==='takeaway'?'สั่งกลับบ้าน '+esc(o.takeaway_id):'โต๊ะ '+esc(o.table_id)}</h3><span class="status">${statuses[o.status]}</span></div><small>${o.received_at} · ${esc(o.session_id||o.pickup_date+' '+o.pickup_slot)} ${old?'· ประวัติรอบที่ปิดแล้ว':''}</small>${itemsHTML(o)}<div class="split"><span>ยอด snapshot เดิม <strong data-testid="front-total" class="amount">${money(o.total)}</strong></span><strong data-testid="front-payment-status">${p.state}</strong></div>${adjustedHTML(o,'front')}<p>วิธีที่เลือก: ${p.method==='cash'?'เงินสด':p.method==='promptpay'?'PromptPay จำลอง':'ยังไม่เลือก'}</p><div class="row">${button('btn-confirm-slip','ยืนยันสลิปจำลอง','confirm-slip',`data-id="${o.id}" ${p.state==='จ่ายแล้ว'||p.requested_at===null?'disabled':''}`)}${button('btn-receive-cash','รับเงินสดจำลอง','receive-cash',`data-id="${o.id}" ${p.state==='จ่ายแล้ว'?'disabled':''}`)}</div></article>`;}).join('')||'<p class="empty">ยังไม่มีออเดอร์</p>'}</div></section><section class="panel"><h2>รอบโต๊ะ</h2><label>เลือกโต๊ะ<select data-testid="front-table-select">${choices(s.tables,u.frontTable,'table_id','label')}</select></label><p>${s.sessions.filter(x=>x.table_id===u.frontTable&&x.state==='open').map(x=>esc(x.id)+' · เปิดรอบ').join('')||'ไม่มีรอบที่เปิดอยู่'}</p><div class="row">${button('','เปิดรอบโต๊ะจำลอง','front-open')}${button('btn-close-table','ปิดรอบโต๊ะที่เลือก','close-table','class="danger"')}</div><p class="muted">ปิดแล้วสั่งต่อรอบเดิมไม่ได้ เก็บออเดอร์เก่าในประวัติ • mock ไม่บังคับจ่ายครบก่อนปิด เพราะ Q-16 ยังไม่ยืนยัน</p><p class="message" role="status">${esc(u.frontMessage)}</p></section><section class="panel"><h2>บันทึกเหตุการณ์ชำระเงิน <span class="tag">จำลอง</span></h2><div data-testid="payment-log">${s.paymentEvents.map(e=>`<p>#${e.order_id} · ${esc(e.actor)} · ${e.at} · ${esc(e.action)}</p>`).join('')||'ยังไม่มีเหตุการณ์'}</div></section>`;}
function managerHTML(){return `<section data-testid="screen-manager"><p>ผู้จัดการจำลอง <strong>${esc(u.user.username)}</strong></p><div class="panel"><label class="check"><input data-testid="toggle-promptpay" type="checkbox" ${s.promptpay?'checked':''}>เปิดบริการ PromptPay จำลอง</label><small>ไม่ตั้งบัญชีธนาคารจริง ไม่มีการสร้าง QR สำหรับโอนเงินจริง</small></div><nav class="subnav" aria-label="งานผู้จัดการ">${button('nav-menu-admin','จัดการเมนู','nav','data-page="menu"')}${button('nav-mapping','แมปวัตถุดิบ','nav','data-page="mapping"')}${button('nav-accounts','บัญชีและ PIN','nav','data-page="accounts"')}${button('nav-capacity','ช่วงเร่งด่วน / ความจุ','nav','data-page="capacity"')}${button('','รายงาน (ตรวจสิทธิ์)','nav','data-page="reports"')}</nav>${staffNav()}${u.page==='menu'?adminHTML():u.page==='mapping'?mappingHTML():u.page==='accounts'?accountsHTML():u.page==='capacity'?capacityHTML():u.page==='reports'?'<section data-testid="report-screen" class="panel"><h2>รายงาน • Placeholder</h2><p>หน้านี้ใช้ตรวจสิทธิ์ US-25 เท่านั้น ไม่สร้างรายงาน US-23 นอกขอบเขต</p></section>':u.page==='kitchen'?kitchenHTML():u.page==='front'?frontHTML():'<div class="panel">เลือกงานจากเมนูด้านบน</div>'}</section>`;}
function loadDraft(id){u.adminId=id;const m=s.menus.find(m=>m.id===id);u.draft=m?clone(m):{name:'',price:0,image:null,available:true,options:[]};u.draft.pendingName='';u.draft.pendingPrice='0';u.draft.imageError='';u.draft.imageLoading=false;}
function adminHTML(){if(!u.draft)loadDraft(u.adminId);const d=u.draft;return `<section data-testid="menu-admin" class="panel"><h2>จัดการเมนู</h2><p class="muted">เพิ่ม/แก้เมนูและตัวเลือก 0–10 รายการ • เมนูที่ส่งแล้วเก็บชื่อและราคาเดิม</p><label>เลือกเมนู<select data-testid="admin-menu-select"><option value="new" ${u.adminId==='new'?'selected':''}>+ สร้างเมนูใหม่</option>${choices(s.menus,u.adminId)}</select></label><div class="fields"><label>ชื่อเมนู<input data-testid="admin-menu-name" value="${esc(d.name)}"></label><label>ราคา (บาท ≥ 0)<input data-testid="admin-menu-price" type="number" min="0" step="0.01" value="${esc(d.price)}"></label><label>รูป jpg/png ≤ 2 MB<input data-testid="admin-menu-image" type="file" accept=".jpg,.jpeg,.png,image/jpeg,image/png"></label></div><label class="check"><input id="admin-available" type="checkbox" ${d.available?'checked':''}>เปิดขายโดยผู้จัดการ (แยกจากวัตถุดิบ)</label>${d.image?`<div class="row"><img alt="รูปเมนูที่เลือก" src="${esc(d.image)}" width="100" height="80" style="object-fit:cover">${button('','นำรูปออก','remove-image')}</div>`:''}<p class="message" role="status">${esc(d.imageError|| (d.imageLoading?'กำลังอ่านรูปในเครื่อง…':''))}</p><h3>ตัวเลือกเพิ่ม (${d.options.length}/10)</h3>${d.options.map((x,i)=>`<div class="option-row"><label>ชื่อตัวเลือก ${i+1}<input data-draft-option="${i}" data-field="name" value="${esc(x.name)}"></label><label>ราคาเพิ่ม<input type="number" min="0" step="0.01" data-draft-option="${i}" data-field="price" value="${esc(x.price)}"></label>${button('','ลบตัวเลือก','remove-option',`data-id="${i}"`)}</div>`).join('')}<div class="fields"><label>ชื่อตัวเลือกใหม่<input data-testid="admin-option-name" value="${esc(d.pendingName)}"></label><label>ราคาเพิ่ม (บาท ≥ 0)<input data-testid="admin-option-price" type="number" min="0" step="0.01" value="${esc(d.pendingPrice)}"></label></div>${button('','เพิ่มตัวเลือกในแบบร่าง','add-option')}<p class="muted">ปุ่มบันทึกเมนูจะรวมตัวเลือกใหม่ที่กรอกค้างไว้ด้วย</p><div class="row">${button('btn-save-menu','บันทึกเมนู','save-menu','class="primary"')}${button('btn-delete-menu','ลบเมนู','delete-menu',`class="danger" ${u.adminId==='new'?'disabled':''}`)}</div><p data-testid="admin-message" class="message" role="status">${esc(u.adminMessage)}</p></section>`;}

function handleRoute(){const route=location.hash.slice(1);if(route.startsWith('/manager/')){if(!can('manager')){u.auth='ปฏิเสธ: ไม่มีสิทธิ์เข้าหน้าผู้จัดการผ่าน URL (จำลอง)';if(u.role!=='customer')u.page='';return render();}const page=route.split('/')[2];u.role='manager';u.page=['menu','mapping','accounts','reports','kitchen','front','capacity'].includes(page)?page:'';render();}else if(route.startsWith('/staff/')){const page=route.split('/')[2];if(!['kitchen','front'].includes(page)||!can(page)){u.page='';return deny();}u.page=page;render();}}
function selectRole(role){epoch++;u.user=null;u.role=role;u.page='';u.auth='';u.draft=null;u.adminMessage='';u.loginUser=role==='manager'?'demomanager':'demokitchen';history.replaceState(null,'',location.pathname+location.search);render();}
function addItem(){const m=s.menus.find(x=>x.id===u.selectedMenu);if(!menuAvailable(m)||m.options.some(o=>u.selectedOptions.includes(o.id)&&!optionAvailable(m,o))){u.orderMessage='ปฏิเสธ: เมนูหรือตัวเลือกหมด / ปิดขาย';return render();}const options=m.options.filter(x=>u.selectedOptions.includes(x.id)).map(clone);const item={menu_id:m.id,name:m.name,price:m.price,options,total:(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100};currentCart().push(item);u.orderMessage='เพิ่มลงตะกร้าแล้ว';render();}
function submitOrder(){const cart=currentCart();if(u.mode==='dine-in'&&session()?.state!=='open'){u.orderMessage='ปฏิเสธ: session โต๊ะปิดแล้ว กรุณาเปิดเมนูใหม่';return render();}if(!cart.length){u.orderMessage='กรุณาเพิ่มอาหารลงตะกร้า';return render();}
 // Validate the entire basket before issuing any order, item, payment or queue entry.
 const invalid=cart.find(i=>{const m=s.menus.find(m=>m.id===i.menu_id);return !menuAvailable(m)||i.options.some(o=>!m.options.some(x=>x.id===o.id)||!optionAvailable(m,o));});
 if(invalid){u.orderMessage='ปฏิเสธ: '+invalid.name+' หรือวัตถุดิบ/ตัวเลือกหมด ถูกปิดขาย หรือถูกลบ กรุณานำรายการออกแล้วเลือกใหม่';return render();}
 // Mock policy: refresh a stale catalog price for review, requiring another submit.
 let changed=false;for(const i of cart){const m=s.menus.find(m=>m.id===i.menu_id),options=i.options.map(o=>clone(m.options.find(x=>x.id===o.id)));const total=(cents(m.price)+options.reduce((n,x)=>n+cents(x.price),0))/100;if(i.price!==m.price||i.name!==m.name||JSON.stringify(i.options)!==JSON.stringify(options)){Object.assign(i,{name:m.name,price:m.price,options,total});changed=true;}}
 if(changed){u.orderMessage='ราคา/รายละเอียดเปลี่ยนแล้ว กรุณาตรวจตะกร้าและกดส่งอีกครั้ง (นโยบายจำลอง)';return render();}
 const slot=u.mode==='takeaway'?slots().find(x=>x.t===u.slot):null;if(u.mode==='takeaway'&&!slot){u.orderMessage='ช่วงรับเดิมผ่านเวลาแล้ว กรุณาเลือกช่วงรับใหม่อย่างน้อย 20 นาที';ensureSlot();return render();}
 let takeaway_id=null;if(u.mode==='takeaway'){if(s.takeawayDay!==day()){s.takeawayDay=day();s.takeawaySequence=0;}takeaway_id='T-'+String(++s.takeawaySequence).padStart(3,'0');}
